package storage

import "kubebench/internal/reason"

// Reasons of the storage plugin's own refusals (docs/design-v0.5.md §3.3).
// Validation reasons name the request field ({{field}}, filled in by
// invalid); detail parameters carry Kubernetes' validation messages.
var (
	reasonNoSnapshots      = reason.Define("storage.no_snapshots", "the cluster does not serve snapshot.storage.k8s.io VolumeSnapshots: install the external-snapshotter CRDs and snapshot controller")
	reasonNoSnapshot       = reason.Define("storage.no_snapshot", "{{field}}: no VolumeSnapshot \"{{name}}\" in namespace \"{{namespace}}\"")
	reasonBoundClone       = reason.Define("storage.bound_clone", "{{field}}: a claim bound to an existing volume cannot be cloned as well")
	reasonSourceKind       = reason.Define("storage.source_kind", "{{field}}: \"{{kind}}\" is not {{pvc}} or {{snapshot}}")
	reasonNoSourceClaim    = reason.Define("storage.no_source_claim", "{{field}}: no PersistentVolumeClaim \"{{name}}\" in namespace \"{{namespace}}\"")
	reasonCloneSize        = reason.Define("storage.clone_size", "{{field}}: a clone must be at least as large as its source ({{size}})")
	reasonRestoreSize      = reason.Define("storage.restore_size", "{{field}}: a restored claim must be at least as large as the snapshot ({{size}})")
	reasonNoVolume         = reason.Define("storage.no_volume", "{{field}}: no PersistentVolume \"{{name}}\"")
	reasonVolumePhase      = reason.Define("storage.volume_phase", "{{field}}: PersistentVolume \"{{name}}\" is {{phase}}, not Available")
	reasonVolumeReserved   = reason.Define("storage.volume_reserved", "{{field}}: PersistentVolume \"{{name}}\" is reserved for {{claim}}")
	reasonVolumeClass      = reason.Define("storage.volume_class", "{{field}}: must be the volume's class ({{class}})")
	reasonVolumeCapacity   = reason.Define("storage.volume_capacity", "{{field}}: PersistentVolume \"{{name}}\" holds only {{size}}")
	reasonVolumeAccessMode = reason.Define("storage.volume_access_mode", "{{field}}: PersistentVolume \"{{name}}\" does not offer {{mode}}")
	reasonVolumeMode       = reason.Define("storage.volume_mode", "{{field}}: PersistentVolume \"{{name}}\" is in {{mode}} mode")
	reasonTooManyParams    = reason.Define("storage.too_many_parameters", "{{field}}: at most {{max}} parameters")
	reasonEmptyKeys        = reason.Define("storage.empty_keys", "{{field}}: keys cannot be empty")
	reasonOneOf            = reason.Define("storage.one_of", "{{field}}: \"{{value}}\" is not {{values}}")
	reasonInvalidName      = reason.Define("storage.invalid_name", "{{field}}: \"{{name}}\" is not a valid name: {{detail}}")
	reasonInvalidNamespace = reason.Define("storage.invalid_namespace", "{{field}}: \"{{name}}\" is not a valid namespace name: {{detail}}")
	reasonQuantity         = reason.Define("storage.quantity", "{{field}}: \"{{value}}\" is not a quantity such as 10Gi or 500M")
	reasonPositive         = reason.Define("storage.positive", "{{field}}: must be greater than zero")
	reasonNoAccessMode     = reason.Define("storage.no_access_mode", "{{field}}: name at least one access mode")
	reasonAccessMode       = reason.Define("storage.access_mode", "{{field}}: \"{{mode}}\" is not an access mode (ReadWriteOnce, ReadOnlyMany, ReadWriteMany or ReadWriteOncePod)")
	reasonListedTwice      = reason.Define("storage.listed_twice", "{{field}}: {{value}} is listed twice")
	reasonRWOPCombined     = reason.Define("storage.rwop_combined", "{{field}}: ReadWriteOncePod cannot be combined with other access modes")
	reasonVolumeModeValue  = reason.Define("storage.volume_mode_value", "{{field}}: \"{{mode}}\" is not a volume mode (Filesystem or Block)")
	reasonTooManyLabels    = reason.Define("storage.too_many_labels", "{{field}}: at most {{max}} labels")
	reasonLabelKey         = reason.Define("storage.label_key", "{{field}}: key \"{{key}}\": {{detail}}")
	reasonLabelValue       = reason.Define("storage.label_value", "{{field}}: value of \"{{key}}\": {{detail}}")
	reasonTooManyOptions   = reason.Define("storage.too_many_mount_options", "{{field}}: at most {{max}} mount options")
	reasonMountOption      = reason.Define("storage.mount_option", "{{field}}: \"{{value}}\" is not a mount option")
	reasonAbsolutePath     = reason.Define("storage.absolute_path", "{{field}}: \"{{value}}\" must be a clean absolute path such as /mnt/data")
	reasonOneSource        = reason.Define("storage.one_source", "{{field}}: set exactly one of hostPath, nfs, local or csi")
	reasonHostPathType     = reason.Define("storage.host_path_type", "{{field}}: \"{{value}}\" is not a hostPath type")
	reasonHostPathBlock    = reason.Define("storage.host_path_block", "{{field}}: a hostPath volume cannot be a raw block device")
	reasonNFSBlock         = reason.Define("storage.nfs_block", "{{field}}: an NFS volume cannot be a raw block device")
	reasonLocalNodes       = reason.Define("storage.local_nodes", "{{field}}: a local volume lives on one node: pick the node(s) it is on")
	reasonNFSNodes         = reason.Define("storage.nfs_nodes", "{{field}}: an NFS volume is reachable from every node and takes no node affinity")
	reasonTooManyNodes     = reason.Define("storage.too_many_nodes", "{{field}}: at most {{max}} nodes")
	reasonNodeName         = reason.Define("storage.node_name", "{{field}}: \"{{value}}\" is not a node name")
	reasonNFSServer        = reason.Define("storage.nfs_server", "{{field}}: \"{{value}}\" is not a host name or IP address")
	reasonFSType           = reason.Define("storage.fs_type", "{{field}}: \"{{value}}\" is not a file system type such as ext4 or xfs")
	reasonNoNode           = reason.Define("storage.no_node", "{{field}}: no node \"{{value}}\"")
	reasonShrinkRequest    = reason.Define("storage.shrink_request", "{{field}}: must be larger than the current request ({{size}}): volumes cannot shrink")
	reasonShrinkCapacity   = reason.Define("storage.shrink_capacity", "{{field}}: must be larger than the current capacity ({{size}})")
	reasonNotBound         = reason.Define("storage.expand_not_bound", "only a Bound claim can be expanded (it is {{phase}})")
	reasonNoClass          = reason.Define("storage.expand_no_class", "the claim has no StorageClass, so it cannot be expanded")
	reasonClassMissing     = reason.Define("storage.expand_class_missing", "the claim's StorageClass {{class}} does not exist")
	reasonNotExpandable    = reason.Define("storage.expand_not_allowed", "the StorageClass {{class}} does not set allowVolumeExpansion")
)
